      "expect": "/browse stable_p95=27 canary_p95=27 | /search stable_p95=59 canary_p95=59 | /checkout stable_p95=103 canary_p95=104"
    },
    {
      "claim": "In the final window (t>=90 s) the canary p95 is within 10 ms of stable p95 and that window contains zero 5xx.",
      "query": "const w=rows.filter(r=>r.t>=90); const S=Math.round(pct(w.filter(r=>r.version==='1.0').map(r=>r.ms),95)), C=Math.round(pct(w.filter(r=>r.version==='1.1').map(r=>r.ms),95)); print('90-120s stable_p95='+S+' canary_p95='+C+' delta='+(C-S)+' window_5xx='+w.filter(r=>r.status>=500).length+' delta_under_10ms='+((C-S)<10));",
      "expect": "window_5xx=0 delta_under_10ms=true"
    },
    {
      "claim": "The slowest request in the test is 339 ms and the same 339 ms maximum occurs on both versions, so the slow tail is not canary-specific.",
      "query": "const mx=a=>a.reduce((m,r)=>r.ms>m?r.ms:m,0); print('stable_max='+mx(stable)+' canary_max='+mx(canary)+' overall_max='+mx(rows));",
      "expect": "stable_max=339 canary_max=339"
    },
    {
      "claim": "The canary served 2411 of 9785 requests, 462 of them /checkout.",
      "query": "print('canary_n='+canary.length+' total_n='+rows.length+' canary_checkout_n='+canary.filter(r=>r.path==='/checkout').length+' share='+(100*canary.length/rows.length).toFixed(1)+'%');",
      "expect": "canary_n=2411 total_n=9785 canary_checkout_n=462"
    }
